#!/usr/bin/env node
const fs = require('fs');

const input = "program_names.json";
const output = "shader-library.js";

const src_dir = "../../src/";
const shaders_dir = src_dir + "shaders/";

let name_list = JSON.parse(fs.readFileSync(input));

let shaders = JSON.parse(fs.readFileSync(shaders_dir + "programs.json"));

// The source without its comments, blank lines and trailing whitespace. The comments are
// read out by a scan over the text, a // to the end of its line and a /* to its */, so that
// a block comment closed on a line that begins with // comes out whole; GLSL has no string
// literals, so nothing else needs care. Every code line keeps its place and indentation,
// the ShaderBuilder directives among them. Half of the shipped text is comments.
function strip(source) {
    let out = "";
    for (let i = 0; i < source.length; ) {
        if (source.startsWith("//", i)) {
            let j = source.indexOf("\n", i);
            i = j < 0 ? source.length : j;
        } else if (source.startsWith("/*", i)) {
            let j = source.indexOf("*/", i + 2);
            i = j < 0 ? source.length : j + 2;
        } else {
            out += source[i++];
        }
    }
    return out.split("\n").map(l => l.trimEnd()).filter(l => l.length > 0).join("\n") + "\n";
}

let programs = {};
let sources = {};
for (let name of name_list) {
    if (shaders[name]) {
        let shdr = shaders[name];
        programs[name] = shdr;

        for (let type in shdr.shaders) {
            let ss = shdr.shaders[type];
            if (sources[ss] === undefined)
                sources[ss] = strip(fs.readFileSync(shaders_dir + ss, "utf8"));
        }
    }
}

let out = "// Generated by pack-shaders.js when the REve bundle is made (make dist), from the programs\n" +
          "// listed in " + input + " and their sources in src/shaders. Not committed.\n\n";
out += "export const programs = " + JSON.stringify(programs, null, 2) + ";\n\n";
out += "export const sources = {\n";
for (let path in sources) {
    out += "  " + JSON.stringify(path) + ":\n    " + JSON.stringify(sources[path]) + ",\n";
}
out += "};\n";

fs.writeFileSync(output, out);
